package com.acgreader.mobile;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.provider.DocumentsContract;import android.webkit.*;import android.view.*;import android.graphics.Color;import android.util.Base64;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.JSONObject;
public class MainActivity extends Activity {
 static final String ORIGIN="https://appassets.androidplatform.net";WebView web;LocalGateway gateway;AlbumSaver albumSaver;boolean albumBusy=false;String albumUrl="",albumToken="";final Bridge bridge=new Bridge();String selectionToken="";boolean destroyed=false;
 @Override public void onCreate(Bundle state){super.onCreate(state);gateway=new LocalGateway(getAssets(),getCacheDir());albumSaver=new AlbumSaver(this,gateway);web=new WebView(this);web.setBackgroundColor(Color.rgb(17,20,18));setContentView(web);web.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets b=insets.getInsets(android.view.WindowInsets.Type.systemBars()|android.view.WindowInsets.Type.displayCutout());v.setPadding(b.left,b.top,b.right,b.bottom);}else{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());}return insets;});
 WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setMediaPlaybackRequiresUserGesture(true);s.setSupportMultipleWindows(true);web.addJavascriptInterface(bridge,"AcgAndroid");
 web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){return gateway.handle(r);}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){String url=r.getUrl().toString();if(url.startsWith(ORIGIN+"/"))return false;if(r.isForMainFrame())external(url);return true;}@Override public void onPageFinished(WebView v,String url){if(url.startsWith(ORIGIN+"/")){try(InputStream in=getAssets().open("mobile.js")){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] part=new byte[8192];int n;while((n=in.read(part))!=-1)bytes.write(part,0,n);js(new String(bytes.toByteArray(),StandardCharsets.UTF_8));}catch(Exception e){alert("手机界面加载失败",e.getMessage());}}}@Override public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())alert("网络连接失败","请检查网络后重新打开应用。");}});
 web.setWebChromeClient(new WebChromeClient(){@Override public boolean onCreateWindow(WebView v,boolean dialog,boolean gesture,Message result){WebView child=new WebView(MainActivity.this);child.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){external(r.getUrl().toString());w.destroy();return true;}});((WebView.WebViewTransport)result.obj).setWebView(child);result.sendToTarget();return true;}});
 web.loadUrl(ORIGIN+"/");}
 void external(String url){Uri uri=Uri.parse(url);if("https".equals(uri.getScheme())||"http".equals(uri.getScheme())){try{startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception ignored){}}}
 void js(String code){runOnUiThread(()->{if(!destroyed)web.evaluateJavascript(code,null);});}
 void alert(String title,String message){runOnUiThread(()->{if(!destroyed)new AlertDialog.Builder(this).setTitle(title).setMessage(message).setPositiveButton("确定",null).show();});}
 @Override public void onBackPressed(){web.evaluateJavascript("(()=>{if(typeof $==='function'&&$('preview')?.open){closePreview();return 1}return typeof saving!=='undefined'&&saving?2:0})()",value->{if("1".equals(value))return;if("2".equals(value)){new AlertDialog.Builder(this).setTitle("正在保存素材").setMessage("退出将中止当前保存，确定退出？").setNegativeButton("继续保存",null).setPositiveButton("退出",(d,w)->finish()).show();}else finish();});}
 @Override protected void onDestroy(){destroyed=true;gateway.cache.close();albumSaver.close();bridge.cancel();web.removeJavascriptInterface("AcgAndroid");web.stopLoading();web.destroy();super.onDestroy();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=41)return;String token=selectionToken;try{if(result!=RESULT_OK||data==null){js("window.androidDirectoryReady("+JSONObject.quote(token)+",false)");return;}Uri tree=data.getData();if(tree==null)throw new IOException("未选择文件夹");getContentResolver().takePersistableUriPermission(tree,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));synchronized(bridge){if(!token.equals(selectionToken))return;bridge.parent=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));bridge.folder=null;}js("window.androidDirectoryReady("+JSONObject.quote(token)+",true)");}catch(Exception e){alert("无法使用该文件夹",e.getMessage());js("window.androidDirectoryReady("+JSONObject.quote(token)+",false)");}}
 void albumResult(boolean ok,String message){runOnUiThread(()->{String token=albumToken;albumBusy=false;albumUrl="";albumToken="";if(!destroyed){android.widget.Toast.makeText(this,message,android.widget.Toast.LENGTH_LONG).show();js("window.androidAlbumSaved("+JSONObject.quote(token)+","+ok+","+JSONObject.quote(message)+")");}});}
 void startAlbumSave(String url,String token){if(destroyed)return;if(albumBusy){js("window.androidAlbumSaved("+JSONObject.quote(token)+",false,\"已有图片正在保存\")");return;}try{if(token.length()>100||url.length()>8000||!gateway.allowed(new java.net.URL(url),false))throw new IOException("图片地址不受支持");albumBusy=true;albumUrl=url;albumToken=token;if(Build.VERSION.SDK_INT<29&&checkSelfPermission(android.Manifest.permission.WRITE_EXTERNAL_STORAGE)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.WRITE_EXTERNAL_STORAGE},42);return;}albumSaver.save(url,this::albumResult);}catch(Exception e){albumToken=token;albumResult(false,e.getMessage());}}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==42){if(results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)albumSaver.save(albumUrl,this::albumResult);else albumResult(false,"未授权保存权限，图片未写入相册");}}
 final class FileState{Uri uri;OutputStream output;FileState(Uri u,OutputStream o){uri=u;output=o;}}
 public final class Bridge {
 @JavascriptInterface public void saveImageToAlbum(String url,String token){runOnUiThread(()->startAlbumSave(url,token));}

 Uri parent,folder;final Map<String,FileState> files=new HashMap<>();boolean cancelled=true;
 @JavascriptInterface public void selectDirectory(String token){runOnUiThread(()->{cancel();selectionToken=token;cancelled=false;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(intent,41);}catch(Exception e){alert("无法打开文件夹选择器",e.getMessage());js("window.androidDirectoryReady("+JSONObject.quote(token)+",false)");}});}
 @JavascriptInterface public synchronized boolean createFolder(String name){try{if(cancelled||parent==null)return false;folder=DocumentsContract.createDocument(getContentResolver(),parent,DocumentsContract.Document.MIME_TYPE_DIR,safe(name));runOnUiThread(()->getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON));return folder!=null;}catch(Exception e){return false;}}
 String safe(String name)throws IOException{if(name==null||name.length()>160||name.contains("/")||name.contains("\\")||name.equals(".")||name.equals(".."))throw new IOException("文件名无效");return name;}
 @JavascriptInterface public synchronized String beginFile(String name,String mime){Uri uri=null;try{if(cancelled||folder==null)return "";uri=DocumentsContract.createDocument(getContentResolver(),folder,mime,safe(name));OutputStream output=getContentResolver().openOutputStream(uri,"w");if(output==null)throw new IOException("无法写入文件");String id=UUID.randomUUID().toString();files.put(id,new FileState(uri,output));return id;}catch(Exception e){if(uri!=null)try{DocumentsContract.deleteDocument(getContentResolver(),uri);}catch(Exception ignored){}return "";}}
 @JavascriptInterface public synchronized boolean writeChunk(String id,String data){try{if(cancelled||data.length()>1500000||!files.containsKey(id))return false;files.get(id).output.write(Base64.decode(data,Base64.DEFAULT));return true;}catch(Exception e){return false;}}
 @JavascriptInterface public synchronized boolean finishFile(String id){FileState f=files.get(id);if(f==null||cancelled)return false;try{f.output.flush();f.output.close();files.remove(id);return true;}catch(Exception e){abortFile(id);return false;}}
 @JavascriptInterface public synchronized void abortFile(String id){FileState f=files.remove(id);if(f!=null){try{f.output.close();}catch(Exception ignored){}try{DocumentsContract.deleteDocument(getContentResolver(),f.uri);}catch(Exception ignored){}}}
 @JavascriptInterface public synchronized void cancel(){gateway.cancelAll();cancelled=true;selectionToken="";for(String id:new ArrayList<>(files.keySet()))abortFile(id);folder=null;runOnUiThread(()->getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON));}
 }
}
